{
  "root_cause": {
    "category": "capacity_saturation",
    "service": "orders",
    "summary": "CPU throttling reduced the orders service worker pool to 1, causing queue buildup and slow responses that led to gateway timeouts and user‑visible errors."
  },
  "confidence": "high",
  "causal_chain": [
    {
      "claim": "At +49.415s, an ops event throttled CPU for the orders service.",
      "status": "confirmed",
      "cites": ["ops-E0001"]
    },
    {
      "claim": "After the throttling, orders service metrics show workers_limit dropped from 16 to 1 starting at +51.635s.",
      "status": "confirmed",
      "cites": ["orders-M000a"]
    },
    {
      "claim": "With only one worker, orders request latency increased and queue length grew, as seen in orders-M000b (+56.635s) where p50=2288ms, p99=3172ms, queue_max=60.",
      "status": "confirmed",
      "cites": ["orders-M000b"]
    },
    {
      "claim": "The gateway began logging upstream timeout errors when calling orders, starting around +54.429s (e.g., gateway-L00070).",
      "status": "confirmed",
      "cites": ["gateway-L00070"]
    },
    {
      "claim": "These timeouts resulted in 504 errors returned to users, visible in gateway metrics where err5xx rose to 79 at +58.304s (gateway-M000b).",
      "status": "confirmed",
      "cites": ["gateway-M000b"]
    }
  ],
  "alternatives": [
    {
      "category": "deploy_regression",
      "service": "gateway",
      "why_less_likely": "The gateway deploy started at +53.799s, after latency had already begun rising (gateway-M000a at +53.304s shows high p50), so the deploy cannot be the initial cause.",
      "cites": ["gateway-M000a", "ops-E0002", "ops-E0003"]
    }
  ]
}
